parameters.jsCode:
// Join BigQuery rows to LLM structured outputs by index, build one supplier email.
const bqRows = $('Execute a SQL query').all().map((item) => item.json);
const llmRows = $input.all().map((item) => item.json);

const fallbackEmail = 'bhannigan@wayfair.com';
const TOP_N = 15;
const configuredSuid = $('Enter Supplier SuID').first().json.supplier_suid;

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function fmtMoney(value) {
  const num = Number(value);
  if (Number.isNaN(num)) return '';
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(num);
}

function fmtNum(value) {
  const num = Number(value);
  if (Number.isNaN(num)) return '';
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(num);
}

function fmtPct(value) {
  if (value === null || value === undefined || value === '') return '';
  const num = Number(value);
  if (Number.isNaN(num)) return String(value);
  return `${num.toFixed(2)}%`;
}

function topComments(text, limit = 2) {
  if (!text) return '';
  const chunks = String(text)
    .split(' || ')
    .map((s) => s.trim())
    .filter(Boolean)
    .slice(0, limit);
  return chunks.join('<br/>');
}

function csvEscape(value) {
  const s = String(value ?? '');
  if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}

if (!bqRows.length) {
  return [
    {
      json: {
        supplier_id: configuredSuid ?? 'N/A',
        supplier_name: 'N/A',
        recipient_email: fallbackEmail,
        subject: "[Action Required] Top Offending SKUs by Buyer's Remorse - Supplier",
        emailHtml:
          '<html><body style="font-family:Arial,sans-serif;">' +
          '<h2>Supplier Buyer\'s Remorse Alert</h2>' +
          '<p>No qualifying SKUs for SuID <b>' + escapeHtml(configuredSuid) + '</b> this week (threshold: &gt; benchmark remorse, +3.0 pts vs L6M, ≥5 returns).</p>' +
          '<p style="color:#666;font-size:12px;">Supplier Buyer\'s Remorse Automation</p>' +
          '</body></html>',
      },
    },
  ];
}

const enriched = bqRows.map((row, idx) => {
  const llm = llmRows[idx] || {};
  const output = llm.output || llm;
  return {
    ...row,
    pdp_summary: output.pdp_summary || llm.pdp_summary || '',
    return_summary: output.return_summary || llm.return_summary || '',
    recommended_action: output.recommended_action || llm.recommended_action || '',
  };
});

const capped = enriched
  .slice()
  .sort((a, b) => Number(a.rank_per_supplier || 999) - Number(b.rank_per_supplier || 999))
  .slice(0, TOP_N);

const supplierName = capped[0].supplier_name || 'Supplier';
const supplierId = capped[0].supplier_id || '';
const benchmarkPct = capped[0].benchmark_buyer_remorse_rate_pct;

const headerCells = [
  'Rank',
  'SKU',
  'Product / Category',
  'WSC L12M',
  'Orders 6W',
  'Returns 6W',
  '6W Remorse',
  'L6M Remorse',
  'Delta pts',
  'Top PDP Reviews',
  'Top Return Comments',
  'PDP Summary',
  'Return Summary',
  'Recommended Action',
];

const tableRowsHtml = capped
  .map((r) => {
    const skuLabel = escapeHtml(r.display_sku || r.internal_sku || '');
    const skuCell = r.pdp_url
      ? `<a href="${escapeHtml(r.pdp_url)}">${skuLabel}</a>`
      : skuLabel;
    const productCategory = `${escapeHtml(r.sku_display_name || '')}<br/><span style="color:#555;">${escapeHtml(r.marketing_category || '')}</span>`;
    const cells = [
      escapeHtml(r.rank_per_supplier),
      skuCell,
      productCategory,
      escapeHtml(fmtMoney(r.wsc_l12m_usd)),
      escapeHtml(fmtNum(r.ordered_units_6w)),
      escapeHtml(fmtNum(r.return_count_6w)),
      escapeHtml(fmtPct(r.recent_buyer_remorse_rate_pct)),
      escapeHtml(fmtPct(r.l6m_buyer_remorse_rate_pct)),
      escapeHtml(r.remorse_rate_l6m_delta_pts),
      topComments(r.customer_pdp_reviews),
      topComments(r.customer_return_comments),
      escapeHtml(r.pdp_summary).replace(/\n/g, '<br/>'),
      escapeHtml(r.return_summary).replace(/\n/g, '<br/>'),
      escapeHtml(r.recommended_action).replace(/\n/g, '<br/>'),
    ];
    return `<tr>${cells.map((c) => `<td style="vertical-align:top;padding:6px;border:1px solid #ddd;font-size:12px;">${c}</td>`).join('')}</tr>`;
  })
  .join('');

const csvHeader = [
  'rank_per_supplier',
  'supplier_id',
  'supplier_name',
  'marketing_category',
  'internal_sku',
  'display_sku',
  'pdp_url',
  'sku_display_name',
  'wsc_l12m_usd',
  'ordered_units_6w',
  'return_count_6w',
  'benchmark_buyer_remorse_rate_pct',
  'recent_buyer_remorse_rate_pct',
  'l6m_buyer_remorse_rate_pct',
  'remorse_rate_l6m_delta_pts',
  'customer_pdp_reviews',
  'customer_return_comments',
  'pdp_summary',
  'return_summary',
  'recommended_action',
];

const csvLines = [csvHeader.join(',')];
for (const r of capped) {
  csvLines.push(
    [
      r.rank_per_supplier,
      r.supplier_id,
      r.supplier_name,
      r.marketing_category,
      r.internal_sku,
      r.display_sku,
      r.pdp_url,
      r.sku_display_name,
      r.wsc_l12m_usd,
      r.ordered_units_6w,
      r.return_count_6w,
      r.benchmark_buyer_remorse_rate_pct,
      r.recent_buyer_remorse_rate_pct,
      r.l6m_buyer_remorse_rate_pct,
      r.remorse_rate_l6m_delta_pts,
      r.customer_pdp_reviews,
      r.customer_return_comments,
      r.pdp_summary,
      r.return_summary,
      r.recommended_action,
    ]
      .map(csvEscape)
      .join(',')
  );
}

const emailHtml = `
<html>
<body style="font-family:Arial,Helvetica,sans-serif;color:#222;">
  <h2 style="margin-bottom:4px;">Supplier Buyer's Remorse Alert</h2>
  <p style="margin-top:0;">Hi ${escapeHtml(supplierName)} team, below are your top offending SKUs by buyer's remorse (max ${TOP_N}). Benchmark: <b>${escapeHtml(fmtPct(benchmarkPct))}</b>; spike threshold: <b>+3.0 pts vs L6M</b>; min returns: <b>5</b>. SuID: <b>${escapeHtml(supplierId)}</b>.</p>
  <table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;max-width:1400px;">
    <thead>
      <tr style="background:#f3f4f6;">
        ${headerCells.map((h) => `<th style="text-align:left;padding:6px;border:1px solid #ddd;font-size:12px;">${h}</th>`).join('')}
      </tr>
    </thead>
    <tbody>
      ${tableRowsHtml}
    </tbody>
  </table>
  <h3 style="margin-top:24px;">CSV (copy/paste into Sheets)</h3>
  <pre style="white-space:pre-wrap;font-size:11px;background:#fafafa;border:1px solid #eee;padding:12px;">${escapeHtml(csvLines.join('\n'))}</pre>
  <p style="color:#666;font-size:12px;margin-top:24px;">Supplier Buyer's Remorse Alert · Supplier-Facing Automation</p>
</body>
</html>`.trim();

return [
  {
    json: {
      supplier_id: supplierId,
      supplier_name: supplierName,
      recipient_email: fallbackEmail,
      subject: `[Action Required] Top Offending SKUs by Buyer's Remorse - ${supplierName}`,
      emailHtml,
      sku_count: capped.length,
    },
  },
];
